using BenchmarkDotNet.Attributes;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;
using OptimizingEfCoreQueries.Shared;
using OptimizingEfCoreQueries.Solutions;

namespace OptimizingEfCoreQueries.Benchmarks;

// Each measured operation simulates a burst of short-lived requests. Baseline
// news-up a DbContext per request; Optimized calls the agent-owned
// ContextPoolingSolution.AcquireContext. Both run the same trivial query so the
// difference is dominated by how the context is obtained. Do not edit this file
// — edit Solutions/ContextPooling.cs.
[Config(typeof(SharedBenchmarkConfig))]
public class ContextPoolingBenchmark
{
    private const int Requests = 3000;
    private SqliteConnection _connection = null!;
    private DbContextOptions<AppDbContext> _options = null!;

    [GlobalSetup]
    public void Setup()
    {
        _connection = AppDbContext.OpenSharedConnection();
        _options = new DbContextOptionsBuilder<AppDbContext>().UseSqlite(_connection).Options;
        using var db = new AppDbContext(_options);
        db.Database.EnsureCreated();
        SeedData.SeedCustomers(db, customers: 20);
    }

    [GlobalCleanup]
    public void Cleanup() => _connection.Dispose();

    [Benchmark(Baseline = true)]
    public int Baseline()
    {
        var total = 0;
        for (var i = 0; i < Requests; i++)
        {
            using var db = new AppDbContext(_options);
            total += db.Customers.AsNoTracking().Count();
        }

        return total;
    }

    [Benchmark]
    public int Optimized()
    {
        var total = 0;
        for (var i = 0; i < Requests; i++)
        {
            using var db = ContextPoolingSolution.AcquireContext(_options);
            total += db.Customers.AsNoTracking().Count();
        }

        return total;
    }
}
